data: {"index":1,"delta":{"text":", complicated place he had long since abandoned. He was content with his tea, his pipe, and the company of the wheel","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":"ing gulls.\n\nThat was until the Tuesday after the equinox. \n\nA severe autumn gale had spent the night","type":"text"},"event_type":"step.delta"}

