data: {"index":1,"delta":{"text":" the stuff of childhood fancy, old sailor yarns meant to amuse greenhorns in coastal taverns. Finding a real one was","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" like catching a ghost by the tail.\n\nBack in the warm, lamplit kitchen of the lighthouse, Silas set the kettle","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" to boil. With the tip of his pocketknife, he chipped away the brittle wax, pulled the cork with a satisfying","type":"text"},"event_type":"step.delta"}

