data: {"index":1,"delta":{"text":" a pair of tweezers, he coaxed the parchment free and laid it flat upon the scarred wooden table.\n\nIt was","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" covered in ink that had faded to the color of rust, written in a neat, sweeping cursive. \n\n*To","type":"text"},"event_type":"step.delta"}

