event: step.delta
data: {"index":1,"delta":{"text":" \n\n*My name is Clara. I write this from the deck of the brigantine *Albatross*, bound for the Carol","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":"inas. We are six days out of port, and the sea has grown heavy. My husband, Thomas, sits across","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" from me, carving a wooden robin for our daughter left behind in Cornwall. The wind is shifting to the northeast. It smells of copper","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" and coming ruin. If you are reading this, it means the sea has won, and I have only this glass vessel to carry","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" my voice to the living world. Do not pity me; the ocean is vast and beautiful, even when it swallows you","type":"text"},"event_type":"step.delta"}

