event: step.delta
data: {"index":1,"delta":{"text":" for a wooden robin that never arrived. For a long time, the kitchen was entirely still, save for the grandfather clock ticking off","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" the seconds in the corner. \n\nSuddenly, the lighthouse around him felt different. It was no longer just a machine","type":"text"},"event_type":"step.delta"}

event: step.delta
