data: {"index":1,"delta":{"text":" the churning, indifferent gray sea. The waves rolled on, uncaring and eternal, hiding their secrets in the dark trenches","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" below. \n\nHe walked back to the table, gently folding the parchment. He placed it inside a small wooden box where","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" he kept his most precious possessions—a faded photograph of his mother, a silver pocket watch that had stopped ticking in 1912","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":". \n\nThat evening, as the sun dipped below the horizon and the great lamp sprang to life, sweeping its brilliant arc","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" of safety across the black water, Silas felt a strange and profound shift. He was no longer just an old man hiding","type":"text"},"event_type":"step.delta"}

